"""Pydantic v2 schemas for the LangGraph Agent Harness State and Working Memory."""

import operator
from typing import Annotated

from pydantic import BaseModel, ConfigDict, Field

from src.schemas.evidence import EvidenceClaim, StructuredEvidenceCard


class SubQueryTask(BaseModel):
    """A decomposed sub-task generated by the Planner for an Isolated Sub-agent Worker."""

    model_config = ConfigDict(extra="forbid")

    sub_query_id: str = Field(..., description="Unique identifier for the sub-query task")
    query_text: str = Field(..., description="Specific question or search objective")
    target_entities: list[str] = Field(
        default_factory=list,
        description="Entities of interest for Temporal Semantic Memory lookup",
    )
    completed: bool = Field(default=False)


class StateSnapshot(BaseModel):
    """Compressed working state produced by Auto-Compaction when token budget threshold is exceeded."""

    model_config = ConfigDict(extra="forbid")

    compaction_step: int = Field(..., description="Iteration number when compaction occurred")
    condensed_reasoning: str = Field(
        ...,
        description="High-density summary of completed investigation steps and findings",
    )
    preserved_citations: list[str] = Field(
        default_factory=list,
        description="All verified source_chunk_ids preserved across compaction",
    )
    tokens_before: int = Field(..., ge=0)
    tokens_after: int = Field(..., ge=0)


class HarnessState(BaseModel):
    """Tier 1 (Working Memory): Root state object managed by the LangGraph StateGraph orchestrator."""

    model_config = ConfigDict(extra="forbid")

    session_id: str = Field(default="default_session")
    user_query: str = Field(..., description="Original complex user research question")
    procedural_rules: list[str] = Field(
        default_factory=list,
        description="Procedural memory strategies loaded at session initialization",
    )
    sub_queries: list[SubQueryTask] = Field(
        default_factory=list,
        description="Decomposed sub-tasks produced by the Planner",
    )
    evidence_cards: Annotated[list[StructuredEvidenceCard], operator.add] = Field(
        default_factory=list,
        description="Compact evidence cards returned by Isolated Sub-agent Workers",
    )
    verified_claims: list[EvidenceClaim] = Field(
        default_factory=list,
        description="Claims that passed the Anti-Poisoning Verification Gate",
    )
    rejected_claims: list[EvidenceClaim] = Field(
        default_factory=list,
        description="Claims rejected due to missing source_chunk_id or low entailment confidence",
    )
    snapshots: list[StateSnapshot] = Field(
        default_factory=list,
        description="Historical Auto-Compaction snapshots",
    )
    scratchpad: str = Field(
        default="",
        description="Working Memory reasoning scratchpad for the Main Agent",
    )
    current_token_estimate: int = Field(
        default=0,
        ge=0,
        description="Current estimated token footprint of the Main Agent Working Memory",
    )
    iteration_count: int = Field(default=0, ge=0)
    needs_more_research: bool = Field(default=False)
    final_report: str = Field(default="", description="Synthesized final report with grounded citations")
